import json,sys
from pathlib import Path
p=Path(sys.argv[1]); errors=[]
def read(name): return json.loads((p/name).read_text(encoding='utf-8'))
router=read('router.json'); summary=read('summary.json'); aliases=read('aliases.json')
for key,value in router['routes'].items():
    if summary['routes'].get(key)!=value: errors.append('summary.json routes.'+key+' differs from router.json')
for name,target in aliases.items():
    seen={name}
    while target in aliases:
        if target in seen: errors.append('aliases.json cycle at '+name); break
        seen.add(target); target=aliases[target]
    if target not in router['capabilities']: errors.append('aliases.json unresolved '+name+' -> '+target)
    declared=router['legacy'].get(name)
    if declared is not None and target!=declared: errors.append('aliases.json '+name+' differs from router.json legacy mapping')
for target in router['capabilities']:
    if not (p/target).is_file(): errors.append('missing '+target)
version=(p/'VERSION').read_text(encoding='utf-8').strip()
if version not in (p/'CHANGELOG.md').read_text(encoding='utf-8'): errors.append('CHANGELOG.md missing version '+version)
print(json.dumps({'checked_directory':str(p),'scope':'fixture route-summary-alias/reference/version consistency only','errors':errors}))
sys.exit(1 if errors else 0)

