import json,sys,re,hashlib
from pathlib import Path
root=Path(__file__).resolve().parent
def local(name):
    p=(root/name).resolve()
    if not p.is_relative_to(root): raise ValueError('outside fixture')
    return p
def read(name): return json.loads(local(name).read_text(encoding='utf-8'))
def digest(folder):
    base=local(folder)
    return {str(p.relative_to(base)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in base.rglob('*') if p.is_file()}
q=read(sys.argv[1]); op=q['op']; result={}; code=0
with local('install-attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f: f.write(json.dumps({'phase':'attempt','request':q})+'\n')
def failure(kind,error,tb):
    with local('install-attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f: f.write(json.dumps({'phase':'error','request':q,'outcome':str(error)})+'\n')
    sys.__excepthook__(kind,error,tb)
sys.excepthook=failure
before=digest('active')
if op=='inspect': result={'active':before,'candidate':digest('candidate')}
elif op=='check':
    folder=q['folder']; manifest=read(folder+'/manifest.json'); missing=[]; checked=[]
    for name in manifest['required_files']:
        p=local(folder+'/'+name)
        if not p.is_file(): missing.append(folder+'/'+name); continue
        checked.append({'path':folder+'/'+name,'resolved':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
        if p.suffix=='.md':
            for ref in re.findall(r'^Reference: (.+)$',p.read_text(encoding='utf-8'),re.M):
                target=(p.parent/ref).resolve()
                if not target.is_relative_to(root) or not target.is_file(): missing.append(str(p)+' -> '+ref)
    result={'folder':folder,'checked':checked,'missing':missing}; code=1 if missing else 0
elif op=='switch':
    source=q.get('source','candidate'); target=q.get('target','active'); manifest=read(source+'/manifest.json'); copied=[]
    for name in manifest['owned_files']:
        src=local(source+'/'+name); dst=local(target+'/'+name); dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(src.read_bytes()); copied.append(name)
        if q.get('simulate_failure',True):
            result={'outcome':'failed','error':'SIMULATED_IO_AFTER_FIRST_FILE','copied':copied,'remaining':manifest['owned_files'][len(copied):]}; code=7; break
    else: result={'outcome':'completed','copied':copied}
elif op=='restore':
    copied=[]
    for name in q['files']:
        src=local('recovery/'+name); dst=local(q.get('target','active')+'/'+name); dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(src.read_bytes()); copied.append(name)
    result={'outcome':'restored','files':copied}
else: raise ValueError('unknown op')
with local('install-attempts.jsonl').open('a',encoding='utf-8',newline='\n') as f: f.write(json.dumps({'phase':'result','request':q,'before_active':before,'result':result,'after_active':digest('active'),'exit':code})+'\n')
print(json.dumps(result)); sys.exit(code)

